/**
 * Databricks Node - Version 1
 * Discriminator: resource=job, operation=run
 */


interface Credentials {
  databricksApi: CredentialReference;
  databricksOAuth2Api: CredentialReference;
}

/** Run and inspect Databricks jobs. <a href="https://docs.databricks.com/jobs/index.html" target="_blank">Learn more</a>. */
export type DatabricksV1JobRunParams = {
  resource: 'job';
  operation: 'run';
  authentication?: 'accessToken' | 'oAuth2' | Expression<string>;
/**
 * The job to work with
 * @searchListMethod getJobs
 * @default {"mode":"list","value":""}
 */
    jobId?: { __rl: true; mode: 'list' | 'id' | 'url'; value: string; cachedResultName?: string };
/**
 * Job-level parameters for this run. They override the default values defined on the job.
 * @default {}
 */
    jobParameters?: {
        /** Parameter
     */
    parameters?: Array<{
      /** Name of a parameter defined on the job
       */
      name?: string | Expression<string>;
      /** Value
       */
      value?: string | Expression<string>;
    }>;
  };
/**
 * Whether to wait until the run finishes and return the final run. When off, the node returns the run ID right away and the job keeps running in Databricks.
 * @default false
 */
    waitForCompletion?: boolean | Expression<boolean>;
/**
 * Options
 * @displayOptions.show { waitForCompletion: [true] }
 * @default {}
 */
    options?: {
    /** Maximum time in seconds to wait for the run to finish. The node fails if the run is still going after this time.
     * @default 600
     */
    timeout?: number | Expression<number>;
  };
};

export type DatabricksV1JobRunNode = {
  type: 'n8n-nodes-base.databricks';
  version: 1;
  config: NodeConfig<DatabricksV1JobRunParams> & { credentials?: Credentials };
};